import sys
import math

def read_input():
    lines = sys.stdin.read().splitlines()
    inputs = []
    for line_index, line in enumerate(lines):
        if not line.strip() or line.startswith('#'):
            continue

        line_inputs = [int(x) for x in line.split()]

        if len(line_inputs) != 2:
            raise Exception(f'Invalid input format at line {line_index + 1}')

        n, m = line_inputs
        inputs.append((n, m))

    return inputs


def solve(n, m):
    if not isinstance(m, (int)) or not 0 <= m - 10 <= 100:
        return "m must be an integer between 0 and 110."

    stations = [i for i in range(1, m + 1)]

    max_volume = 0
    fuel_needed = []
    current_fuel = n

    while True:

        if not stations:
            break

        last_station_reached = False
        station_to_reach = None

        for s in reversed(stations):
            distance_to_cover = abs(s - (current_fuel if last_station_reached else 0))
            range_of_next_reach = n + current_fuel if last_station_reached else current_fuel  # corrected!

            if range_of_next_reach >= distance_to_cover:
                station_to_reach = s
                break

            elif not last_station_reached:  
                max_volume += 1 
                fuel_needed.append(current_fuel)
                current_fuel = n  

        stations.remove(station_to_reach)

    return max_volume


def main():
    inputs = read_input()

    for n, m in inputs:
        print(solve(n, m))

if __name__ == "__main__":
    main()
```

